    // Compute output indices
    int by = blockIdx.y * blockDim.y + threadIdx.y;
    int bx = blockIdx.x * blockDim.x + threadIdx.x;
    if (by < out_h && bx < out_w) {
        float sum = 0.0f;
        for (int c = 0; c < in_channels; ++c) {
            // input channel offset
            for (int kh = 0; kh < kernel_h; ++kh) {
                int iy = by * stride_y + dilation_y * kh - padding_y;
                if (iy >= 0 && iy < height) {
                    for (int kw = 0; kw < kernel_w; ++kw) {
                        int ix = bx * stride_x + dilation_x * kw - padding_x;
                        if (ix >= 0 && ix < width) {
                            sum += input[batch_idx*in_channels*height*width?] ... 
                        }
                    }
                }
            }
        }
        output[by, bx, c] = sum; // but we need to map out index: out[b, oc, i, j]
    }
}
